        showComparison(rows) {
            var that = this;

            if (rows.length > 0) {
                var dataRows = rows.map(function (item, idx) { return item.data; }); // převod z grid metadata-view do pole dto

                if (this.isComparisonInited) {
                    this.addToComparison(dataRows);
                } else {
                    this.isComparisonInited = true;
                    this.comparisonCnt.empty();

                    this.comparator = $('<div class="js-detail-comparator">').appendTo(this.comparisonCnt).gcomparator({
                        items: dataRows,
                        columns: that.mainTable.ggrid("option", "columns"),
                        itemTemplate: "{cislo}",
                        itemchange: function (ev, ctx) {
                            that.comparisonBadge.value = ctx.count.toString();
                            that.comparisonBadge.update();
                        },
                        selection: function (ev, ctx) {
                            that.mainTable.ggrid("activeRow", ctx.item);
                        }
                    });
                }

                for (var row in rows) {
                    rows[row].checked = false;
                }

                this.mainTable.ggrid("refresh");
            }
        }

        addToComparison(rows) {
            this.comparator.gcomparator("addItems", rows);
        }


