        RozpadAkce() {
            var cislo = this.globals.Te1_Msk_Nula;
            var l_nazev_akce: String = "";
            var cnt = this;

            var vybraneRadky: Gordic.Ada.Interface.GAkceDto[];
            vybraneRadky = cnt.find(".js-SeznamDokladu").ggrid("getSelection");                        // načtení přes vyhledání gridu (přes class)
            if (vybraneRadky.length === 1) {                                                            // pokud existuje vybraný záznam

                var l_cislo = vybraneRadky[0].cislo!;
                l_nazev_akce = vybraneRadky[0].nazev!;

                var detailwindow = cnt.navigate(
                    "Gordic.Ada.WebClient.GAkceRozpis",
                    {
                        id: 'RozpisDokladu#',
                        cislo: l_cislo,
                        nazev_akce : l_nazev_akce,
                        AkceFiltrDto: this.filter_akce
                    });

                var windowContent = $.content(detailwindow);

                windowContent.element.on('contentclosed', (ev, ctx) => {
                    cnt.mainTable.ggrid('focus');
                }); // při zavření detailu se nastaví focus na grid
            }
        }

